// CRM Log Page JavaScript
(function($) {
    'use strict';

    function setBusy($btn, busy, label) {
        if (!$btn || !$btn.length) return;
        if (busy) {
            $btn.addClass('is-busy').prop('disabled', true);
            if (label) $btn.data('orig-label', $btn.text()).text(label);
        } else {
            $btn.removeClass('is-busy').prop('disabled', false);
            if ($btn.data('orig-label')) {
                $btn.text($btn.data('orig-label'));
                $btn.removeData('orig-label');
            }
        }
    }

    // Reload CRM log table without reloading the page
    function reloadCrmLogTable() {
        var $table = $('table.wp-list-table');
        if (!$table.length) return;
        
        var $form = $('#messages-filter');
        var paged = $form.find('input[name="paged"]').val() || 1;
        var per_page = $form.find('input[name="per_page"]').val() || 20;
        var orderby = $form.find('input[name="orderby"]').val() || 'created_at';
        var order = $form.find('input[name="order"]').val() || 'DESC';
        
        $.post(window.contactinCrmLog.ajaxUrl || window.ajaxurl, {
            action: 'contactin_get_crm_logs',
            nonce: window.contactinCrmLog.nonce,
            paged: paged,
            per_page: per_page,
            orderby: orderby,
            order: order
        }, function(response) {
            if (response && response.success && response.data && response.data.html) {
                $('.wp-list-table-container').html(response.data.html);
            }
        });
    }

    // Per-page dropdown auto-submit
    $(document).on('change', '.cin-per-page-select', function() {
        var url = new URL(window.location.href);
        var per_page = $(this).val();
        url.searchParams.set('per_page', per_page);
        url.searchParams.set('paged', '1');
        window.location.href = url.toString();
    });

    // Utility: show admin message box
    function showStatus(msg, isError) {
        if (typeof window.cinShowMessage === 'function') {
            window.cinShowMessage(msg, isError ? 'error' : 'success', 4000);
        }
    }

    // AJAX action handler
    function handleAjaxAction(btnSelector, action, confirmMsg, successMsg, failMsg) {
        $(btnSelector).off('click').on('click', function() {
            if (confirmMsg && !window.confirm(confirmMsg)) return;
            var $btn = $(this);
            var nonce = $btn.data('nonce');
            if (!nonce) {
                window.cinShowMessage('Missing security token (nonce).', 'error');
                return;
            }
            setBusy($btn, true, window.contactinCrmLog.i18n?.working || 'Working...');
            $.ajax({
                url: window.contactinCrmLog.ajaxUrl || window.ajaxurl,
                method: 'POST',
                data: {
                    action: action,
                    _ajax_nonce: nonce
                },
                dataType: 'json',
                success: function(response) {
                    if (response && response.success) {
                        window.cinShowMessage((response.data && response.data.message) || successMsg, 'success');
                        setBusy($btn, false);
                        setTimeout(function() {
                            reloadCrmLogTable();
                        }, 1500);
                    } else {
                        window.cinShowMessage((response && response.data && response.data.message) || failMsg, 'error');
                        setBusy($btn, false);
                    }
                },
                error: function(xhr) {
                    window.cinShowMessage('Network error (' + xhr.status + ')', 'error');
                    setBusy($btn, false);
                }
            });
        });
    }

    // Attach handlers
    handleAjaxAction(
        '#contactin-clear-crm-logs',
        'contactin_crm_clear_all_logs',
        'Are you sure you want to CLEAR ALL CRM logs? This will permanently delete all CRM logs.',
        'All logs cleared.',
        'Failed to clear logs.'
    );
    handleAjaxAction(
        '#contactin-prune-crm-btn',
        'contactin_crm_prune_old_logs',
        'Are you sure you want to prune old logs? This will permanently delete CRM logs older than 30 days.',
        'Pruned old logs.',
        'Failed to prune logs.'
    );

    // Download CSV handler - Uses modern cinExportHelper from admin-global
    $('.cin-download-csv').on('click', function(e) {
        e.preventDefault();
        var $btn = $(this);
        var status = $btn.data('status') || 'all';
        var operation = $btn.data('operation') || 'all';
        var nonce = $btn.data('nonce') || window.contactinCrmLog.nonce;
        
        if (!nonce) {
            window.cinShowMessage('Missing security token.', 'error');
            return;
        }

        // Build base URL with all filters
        var baseUrl = (window.contactinCrmLog.ajaxUrl || window.ajaxurl) + 
            '?action=contactinbox_download_crm_csv' +
            '&_ajax_nonce=' + encodeURIComponent(nonce) +
            '&status=' + encodeURIComponent(status) +
            '&operation=' + encodeURIComponent(operation);

        if (typeof window.cinExportHelper === 'function') {
            window.cinExportHelper({
                infoAction: 'contactinbox_crm_export_info',
                baseUrl: baseUrl,
                status: status,
                nonce: nonce,
                ajax_url: window.contactinCrmLog.ajaxUrl || window.ajaxurl
            });
        } else {
            // Fallback: direct download (single file)
            window.location.href = baseUrl;
        }
    });

})(jQuery);
